import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const here = dirname(fileURLToPath(import.meta.url));
const xtermJsPath = require.resolve('@xterm/xterm/lib/xterm.js');
const xtermCssPath = resolve(dirname(xtermJsPath), '../css/xterm.css');
const outputPath = resolve(here, '../src/utils/xtermBundle.generated.ts');

// Keep the renderer local and reviewable. The script/source-map trailer is
// intentionally removed so the WebView never attempts a second network fetch.
const js = readFileSync(xtermJsPath, 'utf8')
  .replace(/\n\/\/#[^\n]*sourceMappingURL=[^\n]*\s*$/u, '')
  .replace(/<\/script/gi, '<\\/script');
const css = readFileSync(xtermCssPath, 'utf8').replace(/<\/style/gi, '<\\/style');

const output = `// Generated by scripts/generate-xterm-bundle.mjs. Do not edit by hand.\n// Source: @xterm/xterm 6.0.0 (MIT).\nexport const XTERM_JS = ${JSON.stringify(js)};\nexport const XTERM_CSS = ${JSON.stringify(css)};\n`;
writeFileSync(outputPath, output);
